#!/usr/bin/env bash
# Creates and fully pre-generates one Finite world per radius on the test server (docs/TEST-SERVER-PLAN.md).
# Usage: pregen.sh <server-dir> <radius>...   e.g. pregen.sh ../finite-test-server 3000 8000
# Each world is rN, seed 12345 (or rN-sSEED with SEED=... set), generated by Chunky in a circle out to radius + 512.
# A finished world holds rN/pregen-done and is skipped. An interrupted one is started again and Chunky
# skips the chunks already on disk; Chunky's saved tasks are not used because they are keyed by dimension
# and so shared by every world folder.
set -euo pipefail

dir=$1; shift
trap 'kill $(jobs -p) 2>/dev/null || true' EXIT # the tail feeding the server's stdin
cd "$dir"

set_prop() { sed -i "/^$1=/d" server.properties; printf '%s=%s\n' "$1" "$2" >> server.properties; }
say() { echo "$*" >> console.in; }

# Waits for a line matching $1 in console.out; fails if the server exits first.
wait_for() {
	until grep -qE "$1" console.out 2>/dev/null; do
		kill -0 "$pid" 2>/dev/null || { echo "server exited before: $1" >&2; exit 1; }
		sleep 2
	done
}

for r in "$@"; do
	world="r$r${SEED:+-s$SEED}"
	if [ -f "$world/pregen-done" ]; then echo "$world: already generated, skipped"; continue; fi

	set_prop level-name "$world"
	set_prop level-seed "${SEED:-12345}"
	set_prop pause-when-empty-seconds -1 # an empty server pauses and stalls Chunky
	set_prop level-type 'finiteworld\:finite'
	set_prop generator-settings "{\"radius\"\\:$r}"

	: > console.in
	: > console.out
	start=$(date +%s)
	tail -f console.in | java ${JAVA_OPTS:--Xmx8G} "-Xlog:gc:file=logs/gc-$world.log" -jar fabric-server-launch.jar nogui > console.out 2>&1 &
	pid=$!
	wait_for 'Done \('

	say "chunky cancel"
	say "chunky confirm"
	say "chunky world minecraft:overworld"
	say "chunky shape circle"
	say "chunky center 0 0"
	say "chunky radius $((r + 512))"
	say "chunky start"
	wait_for 'Task finished for minecraft:overworld'
	grep 'Task finished for minecraft:overworld' console.out
	touch "$world/pregen-done"

	say "stop"
	while kill -0 "$pid" 2>/dev/null; do sleep 1; done # not wait: it would also wait for the tail, which never ends
	kill $(jobs -p) 2>/dev/null || true
	echo "$world: done in $(( $(date +%s) - start )) s, $(du -sh "$world" | cut -f1)"
done
